from __future__ import absolute_import

import time
from selenium.webdriver.common.by import By

from taf.selenium.gnb.oam.coam.cu import pages


class BtsStatus(pages.BtsStatus):
    """
    The class corresponding to BTS status page on selenium coam cu webem, all operations under BTS status
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            super(BtsStatus, self).__init__(driver, version)
            self._instance_dict.update({"DUs Status": DusStatusPageV23R4(driver, version),
                                        "Cells Status": CellsStatusPageV23R4(driver, version),
                                        "NG Links Status": NGLinksStatusPageV23R4(driver, version)})


class DusStatusPageV23R4(pages.DusStatusPage):

    def __init__(self, driver, version):
        super(DusStatusPageV23R4, self).__init__(driver, version)
        self._view_panel = DusStatusPageViewPanelV23R4(driver, version)


class CellsStatusPageV23R4(pages.CellsStatusPage):

    def __init__(self, driver, version):
        super(CellsStatusPageV23R4, self).__init__(driver, version)
        self._view_panel = DusStatusPageViewPanelV23R4(driver, version)
        self.__dict__.update({'get_dus_status_info': self._view_panel.get_cell_info})


class DusStatusPageViewPanelV23R4(pages.DusStatusPageViewPanel):

    def get_cell_status_info(self, cell_id, detail_panel_info_xpath, timeout):
        """
        Method for getting Cell details from details panel for corresponding Cell id

        :param cell_id: str, cell id for corresponding to status info
        :param detail_panel_info_xpath: str, xpath of the element in details panel from where info need to be collected
        :param timeout: int, timeout for the element be available to click

        :return: dict, specific information of DUs or Cells or x2 links accordingly
        """
        status_info = []
        for i in cell_id:
            status_info.append(self._parse_status_info_from_details_panel(
                detail_for_element=self.locator.CELL_ID_XPATH.format(i),
                detail_locator=detail_panel_info_xpath,
                timeout=timeout))
        return status_info

    def _parse_status_info_from_details_panel(self, detail_for_element, detail_locator, timeout):
        """
        Method for parsing status info from details panel

        param detail_for_element: str, xpath of the element for which details panel needs to be opened
        param detail_locator: str, locator in details panel for which info needs to be parsed
        param timeout: int, timeout for the element be available to click

        :return: dict, specific information of parsed info from detail_locator in details panel
        """
        self.click_enabled_element(detail_for_element, timeout)
        try:
            self.click_enabled_element(self.locator.OPEN_DETAILS_PANEL_BUTTON, timeout)
        except Exception:
            element = self._driver.find_element(By.XPATH, self.locator.OPEN_DETAILS_PANEL_BUTTON)
            self._driver.execute_script("arguments[0].click();", element)
            time.sleep(1)
        self.click_enabled_element(self.locator.DETAILS_PANEL_OVERVIEW_BUTTON, timeout)
        detail_info = {}
        detail_text = self.get_text(detail_locator).splitlines()
        if self.element_exists(self.locator.CLOSE_DETAILS_PANEL_BUTTON, timeout):
            self.click_enabled_element(self.locator.CLOSE_DETAILS_PANEL_BUTTON, timeout)
            time.sleep(1)
        for i in range(0, len(detail_text)):
            if ':' in detail_text[i]:
                detail_info.update({detail_text[i].split(":")[0].strip(): detail_text[i + 1].strip()})
        return detail_info

    def get_cell_info(self, get_info, cell_id, timeout=60):
        info_mapping = {
            'Cells': self.locator.DETAILS_PANEL_CELL_DETAILS,
            'DUs': self.locator.DETAILS_PANEL_DU_DETAILS,
            'X2_Links_Status': self.locator.DETAILS_PANEL_X2_LINK_DETAILS,
            'NG_Links_Status': self.locator.DETAILS_PANEL_NG_LINK_DETAILS
        }
        detail_panel_info_xpath = info_mapping.get(get_info, self.locator.DETAILS_PANEL_NG_LINK_DETAILS)
        return self.get_cell_status_info(cell_id=cell_id, detail_panel_info_xpath=detail_panel_info_xpath,
                                         timeout=timeout)


class NGLinksStatusPageV23R4(object):
    """
    As a class will be called by BtsStatus, all operations on DUs Status page will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['shield-check', 'NG Links Status']

    def __init__(self, driver, version):
        self._view_panel = DusStatusPageViewPanelV23R4(driver, version)
        self.__dict__.update({'get_dus_status_info': self._view_panel.get_cell_info})
